import sys
from collections import defaultdict

def main():
    sums = defaultdict(float)
    lines = sys.stdin.buffer
    next(lines, None)
    for line in lines:
        _, cat, val = line.split(b',')
        sums[cat] += float(val)
    for cat in sorted(sums):
        print(f"{cat.decode()},{sums[cat]:.2f}")

if __name__ == '__main__':
    main()

